import hmac
import json

from payhook.errors import InvalidNotification


_ALLOWED_SKEW_SECONDS = 300


def _header(headers, name):
    """Return a header value, treating mapping keys as case-insensitive."""
    try:
        value = headers[name]
    except (KeyError, TypeError):
        lower_name = name.lower()
        try:
            items = headers.items()
        except AttributeError as exc:
            raise InvalidNotification("missing headers") from exc
        for key, value in items:
            if isinstance(key, str) and key.lower() == lower_name:
                return value
        raise InvalidNotification(f"missing {name}")
    return value


def _ascii_header_value(value, field):
    if not isinstance(value, str):
        raise InvalidNotification(f"malformed {field}")
    try:
        return value.encode("ascii")
    except UnicodeEncodeError as exc:
        raise InvalidNotification(f"malformed {field}") from exc


def _valid_hex_digest(value):
    if len(value) != 64:
        return False
    return all(char in "0123456789abcdefABCDEF" for char in value)


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if not isinstance(raw_body, (bytes, bytearray)):
        raise InvalidNotification("malformed body")
    body = bytes(raw_body)

    timestamp_text = _header(headers, "X-Pay-Timestamp")
    timestamp_bytes = _ascii_header_value(timestamp_text, "timestamp")
    if not timestamp_text.isdecimal():
        raise InvalidNotification("malformed timestamp")
    timestamp = int(timestamp_text)
    if abs(now - timestamp) > _ALLOWED_SKEW_SECONDS:
        raise InvalidNotification("stale timestamp")

    signature = _header(headers, "X-Pay-Signature")
    if not isinstance(signature, str) or not signature.startswith("v1="):
        raise InvalidNotification("malformed signature")
    provided_digest = signature[3:]
    if not _valid_hex_digest(provided_digest):
        raise InvalidNotification("malformed signature")

    if isinstance(secret, str):
        secret_bytes = secret.encode("utf-8")
    elif isinstance(secret, (bytes, bytearray)):
        secret_bytes = bytes(secret)
    else:
        raise InvalidNotification("malformed secret")

    signed_payload = timestamp_bytes + b"." + body
    expected_digest = hmac.new(secret_bytes, signed_payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(provided_digest.lower(), expected_digest):
        raise InvalidNotification("bad signature")

    try:
        data = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidNotification("malformed JSON") from exc
    if not isinstance(data, dict):
        raise InvalidNotification("malformed JSON")

    event_id = data.get("event_id")
    if not isinstance(event_id, str) or event_id == "":
        raise InvalidNotification("malformed event_id")

    account_id = data.get("account_id")
    if not isinstance(account_id, str) or account_id == "":
        raise InvalidNotification("malformed account_id")

    amount_minor = data.get("amount_minor")
    if (not isinstance(amount_minor, int) or isinstance(amount_minor, bool)
            or amount_minor < 0):
        raise InvalidNotification("malformed amount_minor")

    currency = data.get("currency")
    if (not isinstance(currency, str) or len(currency) != 3
            or not currency.isascii() or not currency.isupper()
            or not currency.isalpha()):
        raise InvalidNotification("malformed currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
"}
